using namespace std;

const int MOD = 15;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    cin >> S;
    int L = S.size();

    // pref[i][m]：前i个字符的所有前缀中，模15 = m 的个数
    vector<vector<long long>> pref(L + 1, vector<long long>(MOD, 0));
    pref[0][0] = 1;          // 空前缀模15为0
    int cur = 0;
    for (int i = 1; i <= L; i++) {
        cur = (cur * 10 + (S[i - 1] - '0')) % MOD;
        for (int m = 0; m < MOD; m++) {
            pref[i][m] = pref[i - 1][m];
        }
        pref[i][cur]++;
    }

    long long ans = 0;
    int suf = 0;   // V_C mod 15
    int w = 1;     // 10^{len_C} mod 15

    // 从后向前枚举删除子串的结束位置 j
    for (int j = L - 1; j >= 0; j--) {
        for (int m = 0; m < MOD; m++) {
            if ((m * w + suf) % MOD == 0) {
                ans += pref[j][m];
            }
        }
        // 更新后缀信息（为下一轮 j-1 做准备）
        if (j > 0) {
            int digit = S[j] - '0';
            suf = (suf + digit * w) % MOD;
            w = (w * 10) % MOD;
        }
    }

    ans--;  // 减去删除整个字符串的方案
    cout << ans << endl;

    return 0;
}
